    Select-String -Path $_.FullName -Pattern "session_search|session_event|name:\s*['\"]session" -ErrorAction SilentlyContinue
  } | Select-Object -First 10 | ForEach-Object {"$([System.IO.Path]::GetFileName($_.Path)):$($_.LineNumber): $($_.Line.Trim())"}
} else { Write-Host "dsh-tool-session-query not found; search broadly" ; Get-ChildItem $nm -Directory | ? {$_.Name -match 'session-query'} | Select-Object Name }

$nm="D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh\node_modules\@deepseek-ai"
Get-ChildItem $nm -Directory | Where-Object {$_.Name -match 'session-query|session-search'} | Select-Object Name
Write-Host "=== find where session_search tool is defined ==="
Get-ChildItem $nm -Directory | ForEach-Object {
  $lib=Join-Path $_.FullName "lib"
  if(Test-Path $lib){
    $m=Select-String -Path "$lib\*.js" -Pattern "name:\s*['\"]session_search|['\"]session_search['\"]" -ErrorAction SilentlyContinue
    if($m){ $_.Name; $m | Select-Object -First 2 | ForEach-Object {"   $($_.Line.Trim())"} }
