cd C:\Users\Administrator\.dsh\profiles\web
$ts=Get-Date -Format "yyyyMMddHHmmss"
$bak="cordis.patch.yml.bak-b2-$ts"
Copy-Item cordis.patch.yml $bak
Write-Host "backup: $bak"
# Apply: (B2-1) add disabled after tool-workflow name INSIDE preset-standard; (B2-2) add disabled after optional-tool-session-query (top-level)
python -c @"
import io,re
p='cordis.patch.yml'
lines=io.open(p,encoding='utf-8').read().split('\n')
# B2-1: find tool-workflow within preset-standard block
s=next(i for i,l in enumerate(lines) if l.strip()=='- id: preset-standard')
e=next(i for i in range(s+1,len(lines)) if lines[i].startswith('- id: '))
def add_disabled_in(block_s, block_e, tid):
    for j in range(block_s, block_e):
        if lines[j].strip()=='- id: '+tid:
            for k in range(j+1,min(j+4,block_e)):
                if lines[k].strip().startswith('name:'):
                    if not (k+1<block_e and lines[k+1].strip()=='disabled: true'):
                        ind=lines[k][:len(lines[k])-len(lines[k].lstrip())]
                        lines.insert(k+1, ind+'disabled: true')
                    return True
    return False
assert add_disabled_in(s,e,'tool-workflow'), 'tool-workflow not in standard'
# B2-2: top-level optional-tool-session-query (first occurrence after re-scan)
# re-find indices as file changed
def add_disabled_top(tid):
    for j in range(len(lines)):
        if lines[j].strip()=='- id: '+tid:
            for k in range(j+1,min(j+4,len(lines))):
                if lines[k].strip().startswith('name:'):
                    if not (k+1<len(lines) and lines[k+1].strip()=='disabled: true'):
                        ind=lines[k][:len(lines[k])-len(lines[k].lstrip())]
                        lines.insert(k+1, ind+'disabled: true')
                    return True
    return False
assert add_disabled_top('optional-tool-session-query'), 'optional-tool-session-query not found'
io.open(p,'w',encoding='utf-8',newline='\n').write('\n'.join(lines))
print('applied. lines:',len(lines))
"@ 2>&1

